<?php
if(!defined('ABSPATH'))exit;
function sscwp_asset($path){if(!$path)return '';if(preg_match('~^(?:https?:|mailto:|tel:|#)~',$path))return $path;$file=basename($path);$map=get_option('sscwp_media_map',[]);return isset($map[$file])?wp_get_attachment_url($map[$file]):get_theme_file_uri('assets/'.$file);}
function sscwp_url($url){if(!$url)return '';if(str_starts_with($url,'assets/'))return sscwp_asset($url);if(str_starts_with($url,'/#/'))$url=substr($url,2);elseif(str_starts_with($url,'#/'))$url=substr($url,1);if(!str_starts_with($url,'/'))return $url;$parts=wp_parse_url($url);$path=rtrim(preg_replace('/\.html$/','',$parts['path']??'/'),'/');if(!$path)$path='/';if(str_starts_with($path,'/om-oss/nyheter'))$path=str_replace('/om-oss/nyheter','/nyheter',$path);if(str_starts_with($path,'/produkt/'))$path=str_replace('/produkt/','/produkter/',$path);if(str_starts_with($path,'/kategori/'))$path=str_replace('/kategori/','/produktkategorier/',$path);$routes=get_option('sscwp_route_map',[]);return ($routes[$path]??home_url($path.'/')).(isset($parts['query'])?'?'.$parts['query']:'').(isset($parts['fragment'])?'#'.$parts['fragment']:'');}
function sscwp_attributes($a){$out='';if(!empty($a['className']))$out.=' class="'.esc_attr($a['className']).'"';if(!empty($a['style']))$out.=' style="'.esc_attr(safecss_filter_attr($a['style'])).'"';foreach(($a['htmlAttrs']??[]) as $key=>$value){if(!preg_match('/^(id|href|target|rel|role|tabindex|type|hidden|datetime|aria-[a-z-]+|data-[a-z-]+)$/',$key))continue;if($key==='href')$value=esc_url(sscwp_url($value));else $value=esc_attr($value);$out.=' '.$key.'="'.$value.'"';}return $out;}
function sscwp_svg($html){return wp_kses($html,['svg'=>['class'=>true,'viewbox'=>true,'viewBox'=>true,'xmlns'=>true,'aria-hidden'=>true,'width'=>true,'height'=>true,'fill'=>true,'stroke'=>true,'stroke-width'=>true,'stroke-linecap'=>true,'stroke-linejoin'=>true],'path'=>['d'=>true,'fill'=>true,'stroke'=>true],'circle'=>['cx'=>true,'cy'=>true,'r'=>true],'polyline'=>['points'=>true],'rect'=>['x'=>true,'y'=>true,'width'=>true,'height'=>true,'rx'=>true]]);}
function sscwp_icon($name){static $icons=null;if($icons===null)$icons=json_decode(file_get_contents(get_theme_file_path('seed/icons.json')),true);return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'.esc_attr($icons[$name]??$icons['arrow']).'"/></svg>';}
function sscwp_arrow(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-5-5 5 5-5 5"/></svg>';}
function sscwp_image($file,$alt='',$class='',$lazy=true){if(!$file)return '';return '<img src="'.esc_url(sscwp_asset($file)).'" alt="'.esc_attr($alt).'" class="'.esc_attr($class).'" '.($lazy?'loading="lazy"':'fetchpriority="high"').' decoding="async">';}
function sscwp_render($a,$content,$block){
 $name=substr($block->name,4);
 if($name==='container'){$tag=$a['tag']??'div';if(!in_array($tag,['div','section','article','nav','header','footer','aside','figure','ul','ol','li','dl','dt','dd','a','button','form'],true))$tag='div';return '<'.$tag.sscwp_attributes($a).'>'.$content.'</'.$tag.'>';}
 if($name==='text'){$tag=$a['tag']??'p';if(!in_array($tag,['h1','h2','h3','h4','h5','h6','p','span','strong','small','time','figcaption','caption','summary','label','address'],true))$tag='p';return '<'.$tag.sscwp_attributes($a).'>'.wp_kses_post($a['html']??'').'</'.$tag.'>';}
 if($name==='link'){return '<a href="'.esc_url(sscwp_url($a['url']??'')).'"'.sscwp_attributes($a).'>'.wp_kses_post($a['html']??'').'</a>';}
 if($name==='image'){$url=!empty($a['id'])?wp_get_attachment_url($a['id']):sscwp_asset($a['url']??'');if(!$url)return '';return '<img src="'.esc_url($url).'" alt="'.esc_attr($a['alt']??'').'" class="'.esc_attr($a['className']??'').'" '.(($a['loading']??'lazy')==='lazy'?'loading="lazy"':'fetchpriority="high"').' decoding="async">';}
 if($name==='icon')return sscwp_svg($a['svg']??'');
 if($name==='disclosure')return '<details class="'.esc_attr($a['className']??'').'"'.(!empty($a['open'])?' open':'').'><summary>'.wp_kses($a['title']??'Öppna',array_merge(wp_kses_allowed_html('post'),['svg'=>['class'=>true,'viewbox'=>true,'viewBox'=>true,'aria-hidden'=>true],'path'=>['d'=>true]])).'</summary>'.$content.'</details>';
 if($name==='table'){$out='<table class="'.esc_attr($a['className']??'spec-table').'">';if(!empty($a['caption']))$out.='<caption class="sr-only">'.esc_html($a['caption']).'</caption>';foreach(($a['rows']??[])as $i=>$row){$out.='<tr>';foreach($row as $cell){$tag=($cell['tag']??'td')==='th'?'th':'td';$out.='<'.$tag.'>'.wp_kses_post($cell['html']??'').'</'.$tag.'>';}$out.='</tr>';}return $out.'</table>';}
 if($name==='breadcrumbs'){$items=$a['items']??[];if(!$items&&is_tax('ssc_category'))$items=[['name'=>'Start','url'=>'/'],['name'=>'Produkter','url'=>'/produkter'],['name'=>single_term_title('',false),'url'=>'']];$out='<div class="breadcrumb-bar"><div class="wrap"><nav class="breadcrumbs" aria-label="Brödsmulor">';foreach($items as $i=>$item){if($i)$out.='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>';$label=$item['name'];if($i===count($items)-1&&is_singular(['ssc_product','ssc_news','ssc_customer']))$label=get_the_title();$out.=!empty($item['url'])?'<a href="'.esc_url(sscwp_url($item['url'])).'">'.esc_html($label).'</a>':'<span aria-current="page">'.esc_html($label).'</span>';}return $out.'</nav></div></div>';}
 if($name==='catalog')return sscwp_catalog($a);
 if($name==='product-section')return sscwp_product_section($a['section']??'hero');
 return $content;
}
add_action('init',function(){
 wp_register_script('sscwp-editor',get_theme_file_uri('assets/editor.js'),['wp-blocks','wp-element','wp-block-editor','wp-components','wp-data','wp-plugins','wp-editor','wp-server-side-render'],SSCWP_VERSION,true);
 foreach(glob(get_theme_file_path('blocks/*/block.json')) as $file)register_block_type(dirname($file),['render_callback'=>'sscwp_render','editor_script'=>'sscwp-editor']);
});
